// Récupère tous les fichiers extraits
const items = $input.all();
const startTime = Date.now();

// Initialise les catégories
const pdfs = [];
const excels = [];
const ignored = [];

// Trie les fichiers
for (const item of items) {
  const fileName = item.json.fileName || 'unknown';
  const binaryData = item.binary?.data;

  if (!binaryData) {
    ignored.push({ fileName, reason: 'Pas de données binaires' });
    continue;
  }

  // Calcule la taille en bytes
  const fileSize = Buffer.from(binaryData.data, 'base64').length;
  const fileSizeMB = (fileSize / 1024 / 1024).toFixed(2);
  const ext = fileName.toLowerCase().split('.').pop();

  if (ext === 'pdf') {
    // Filtre < 10 MB
    if (fileSize < 10485760) { // 10 MB en bytes
      pdfs.push({
        fileName,
        fileSize,
        fileSizeMB,
        base64Data: binaryData.data
      });
    } else {
      ignored.push({ 
        fileName, 
        reason: `Taille ${fileSizeMB} MB > 10 MB (plan technique ignoré)` 
      });
    }
  } else if (ext === 'xlsx' || ext === 'xls') {
    excels.push({
      fileName,
      fileSizeMB
    });
  } else {
    ignored.push({ fileName, reason: `Type ${ext} non pris en charge` });
  }
}

// Trie les PDFs par taille (décroissant)
pdfs.sort((a, b) => b.fileSize - a.fileSize);

// Limite à 40 PDFs
const selectedPdfs = pdfs.slice(0, 40);

if (pdfs.length > 40) {
  ignored.push({ 
    fileName: `${pdfs.length - 40} PDFs supplémentaires`, 
    reason: 'Limite POC dépassée (40 max)' 
  });
}

// Retourne les PDFs avec métadonnées partagées
return selectedPdfs.map(pdf => ({
  json: {
    fileName: pdf.fileName,
    fileSize: pdf.fileSize,
    fileSizeMB: pdf.fileSizeMB + ' MB',
    base64Data: pdf.base64Data,
    // Métadonnées globales (propagées)
    _metadata: {
      startTime,
      totalFiles: items.length,
      totalPdfs: pdfs.length,
      selectedPdfs: selectedPdfs.length,
      excelFiles: excels,
      ignoredFiles: ignored
    }
  }
}));

// Configuration API Claude
const ANTHROPIC_API_KEY = 'YOUR_API_KEY_HERE'; // ⚠️ REMPLACE PAR TA CLÉ
const API_URL = 'https://api.anthropic.com/v1/messages';

// Récupère les données du PDF
const fileName = $input.item.json.fileName;
const base64Data = $input.item.json.base64Data;
const metadata = $input.item.json._metadata;

// Prompt de classification
const classificationPrompt = `Tu es un expert en appels d'offres BTP.

Analyse ce document et identifie son TYPE en 1 MOT parmi :
- CCAP (Cahier des Clauses Administratives Particulières)
- REGLEMENT (Règlement de consultation)
- PLANNING (Planning des travaux, calendrier)
- NOTICE (Notice technique, descriptif)
- DPGF (Détail Quantitatif Estimatif / Bordereau de prix)
- PLANS (Plans techniques, schémas)
- ANNEXE (Annexes diverses)
- INCONNU (si tu ne peux pas déterminer)

IMPORTANT : 
- Ignore les pages de garde administratives (logos, en-têtes)
- Concentre-toi sur le contenu principal (généralement à partir de la page 3-5)
- Si le document est un MODIFICATIF ou AVENANT, indique le type de base (ex: CCAP)

Réponds UNIQUEMENT avec le mot-clé en MAJUSCULES, RIEN d'autre.

Exemple de réponse valide : CCAP

Réponse :`;

// Prépare le payload pour Claude
const payload = {
  model: 'claude-3-5-sonnet-20241022',
  max_tokens: 50,
  messages: [
    {
      role: 'user',
      content: [
        {
          type: 'document',
          source: {
            type: 'base64',
            media_type: 'application/pdf',
            data: base64Data
          }
        },
        {
          type: 'text',
          text: classificationPrompt
        }
      ]
    }
  ]
};

// Appel API avec gestion d'erreur
try {
  const response = await fetch(API_URL, {
    method: 'POST',
    headers: {
      'x-api-key': ANTHROPIC_API_KEY,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json'
    },
    body: JSON.stringify(payload)
  });

  if (!response.ok) {
    throw new Error(`API Error: ${response.status} ${response.statusText}`);
  }

  const result = await response.json();

  // Extrait le type du contenu de la réponse
  const rawType = result.content[0]?.text?.trim().toUpperCase() || 'INCONNU';

  // Nettoie la réponse (parfois Claude ajoute du texte)
  const validTypes = ['CCAP', 'REGLEMENT', 'PLANNING', 'NOTICE', 'DPGF', 'PLANS', 'ANNEXE', 'INCONNU'];
  let documentType = 'INCONNU';

  for (const type of validTypes) {
    if (rawType.includes(type)) {
      documentType = type;
      break;
    }
  }

  return {
    json: {
      fileName,
      fileSize: $input.item.json.fileSize,
      fileSizeMB: $input.item.json.fileSizeMB,
      base64Data,
      documentType,
      classificationRaw: rawType,
      _metadata: metadata
    }
  };

} catch (error) {
  // En cas d'erreur, continue avec type ERREUR
  return {
    json: {
      fileName,
      fileSize: $input.item.json.fileSize,
      fileSizeMB: $input.item.json.fileSizeMB,
      base64Data,
      documentType: 'ERREUR',
      classificationError: error.message,
      _metadata: metadata
    }
  };
}

// Récupère tous les documents classifiés
const items = $input.all();

// Types pertinents pour analyse détaillée
const relevantTypes = ['CCAP', 'REGLEMENT', 'PLANNING', 'NOTICE'];

// Compteurs et listes
const typeCount = {};
const relevantDocs = [];
const ignoredDocs = [];
const errorDocs = [];

// Trie les documents
for (const item of items) {
  const type = item.json.documentType;
  const fileName = item.json.fileName;

  // Compte les occurrences
  typeCount[type] = (typeCount[type] || 0) + 1;

  if (type === 'ERREUR') {
    errorDocs.push({
      fileName,
      error: item.json.classificationError || 'Erreur inconnue'
    });
  } else if (relevantTypes.includes(type)) {
    relevantDocs.push(item.json);
  } else {
    ignoredDocs.push({
      fileName,
      type
    });
  }
}

// Détecte les doublons (plusieurs docs du même type)
const duplicates = [];
for (const [type, count] of Object.entries(typeCount)) {
  if (count > 1 && relevantTypes.includes(type)) {
    duplicates.push({
      type,
      count,
      warning: `⚠️ ${count} documents de type ${type} détectés - Vérifier les versions/modificatifs`
    });
  }
}

// Récupère les métadonnées du premier item
const metadata = items[0]?.json._metadata || {};

// Ajoute les nouvelles métadonnées
const enrichedMetadata = {
  ...metadata,
  classificationComplete: true,
  relevantDocsCount: relevantDocs.length,
  ignoredDocsCount: ignoredDocs.length,
  errorDocsCount: errorDocs.length,
  duplicates,
  ignoredDocs,
  errorDocs
};

// Retourne uniquement les docs pertinents pour analyse
if (relevantDocs.length === 0) {
  // Cas spécial : aucun doc pertinent trouvé
  return [{
    json: {
      noRelevantDocs: true,
      _metadata: enrichedMetadata
    }
  }];
}

return relevantDocs.map(doc => ({
  json: {
    ...doc,
    _metadata: enrichedMetadata
  }
}));

// Configuration API Claude
const ANTHROPIC_API_KEY = 'YOUR_API_KEY_HERE'; // ⚠️ REMPLACE PAR TA CLÉ
const API_URL = 'https://api.anthropic.com/v1/messages';

// Gère le cas "aucun doc pertinent"
if ($input.item.json.noRelevantDocs) {
  return {
    json: {
      noRelevantDocs: true,
      _metadata: $input.item.json._metadata
    }
  };
}

// Récupère les données
const fileName = $input.item.json.fileName;
const documentType = $input.item.json.documentType;
const base64Data = $input.item.json.base64Data;
const metadata = $input.item.json._metadata;

// Vérifie si c'est un doublon
const isDuplicate = metadata.duplicates?.some(d => d.type === documentType) || false;
const duplicateWarning = isDuplicate 
  ? `\n⚠️ ATTENTION : Plusieurs documents de type ${documentType} dans ce DCE. Vérifie s'il s'agit d'une version modificative.`
  : '';

// Détecte les mots-clés modificatifs dans le nom
const isModificatif = /modif|avenant|rectif|complement|addendum|v[0-9]|version/i.test(fileName);

// Prompt d'analyse détaillée
const analysisPrompt = `Tu analyses un document d'appel d'offres BTP.

CONTEXTE :
- Type de document : ${documentType}
- Nom du fichier : ${fileName}${duplicateWarning}
${isModificatif ? '- 🔄 POSSIBLE MODIFICATIF (détecté dans le nom)' : ''}

TÂCHE :
1. ${isModificatif ? 'SI MODIFICATIF → Identifie clairement CE QUI CHANGE par rapport à un document précédent' : 'Extrais les informations LES PLUS CRITIQUES pour décider de répondre à cet appel d\'offres'}
2. Identifie TOUTES les dates et délais mentionnés
3. Résume le périmètre/scope du document en 1 phrase

FORMAT DE RÉPONSE (respecte exactement cette structure) :

${isModificatif ? '🔄 MODIFICATIF DÉTECTÉ\n' : ''}**Scope** : [Description concise du périmètre en 1-2 phrases]

**Points critiques** :
- [Information critique 1]
- [Information critique 2]
- [Information critique 3]
${documentType === 'CCAP' || documentType === 'REGLEMENT' ? '- [Information critique 4]\n- [Information critique 5]' : ''}

**⏰ Dates clés** : [Liste toutes les dates trouvées avec leur contexte, ou "Aucune date identifiée"]

${isModificatif ? '\n⚠️ **Impact du modificatif** : [Résumé de ce qui change]' : ''}

IMPORTANT :
- Sois CONCIS et FACTUEL
- Ignore les pages de garde administratives
- Concentre-toi sur les OBLIGATIONS, DÉLAIS, CRITÈRES DE SÉLECTION
- Pour un CCAP : focalisé sur pénalités, garanties, modalités paiement
- Pour un REGLEMENT : focalisé sur critères de jugement, procédure
- Pour un PLANNING : focalisé sur jalons et contraintes temporelles
- Pour une NOTICE : focalisé sur exigences techniques critiques`;

// Prépare le payload
const payload = {
  model: 'claude-3-5-sonnet-20241022',
  max_tokens: 1024,
  messages: [
    {
      role: 'user',
      content: [
        {
          type: 'document',
          source: {
            type: 'base64',
            media_type: 'application/pdf',
            data: base64Data
          }
        },
        {
          type: 'text',
          text: analysisPrompt
        }
      ]
    }
  ]
};

// Appel API avec gestion d'erreur
try {
  const startAnalysis = Date.now();

  const response = await fetch(API_URL, {
    method: 'POST',
    headers: {
      'x-api-key': ANTHROPIC_API_KEY,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json'
    },
    body: JSON.stringify(payload)
  });

  if (!response.ok) {
    throw new Error(`API Error: ${response.status} ${response.statusText}`);
  }

  const result = await response.json();
  const analysisTime = ((Date.now() - startAnalysis) / 1000).toFixed(1);

  // Extrait le contenu de l'analyse
  const analysisContent = result.content[0]?.text || 'Aucune analyse générée';

  return {
    json: {
      fileName,
      documentType,
      fileSizeMB: $input.item.json.fileSizeMB,
      analysis: analysisContent,
      analysisTime: analysisTime + 's',
      isModificatif,
      isDuplicate,
      _metadata: metadata
    }
  };

} catch (error) {
  // En cas d'erreur, retourne un résultat d'erreur
  return {
    json: {
      fileName,
      documentType,
      fileSizeMB: $input.item.json.fileSizeMB,
      analysis: '❌ Erreur lors de l\'analyse de ce document',
      analysisError: error.message,
      analysisTime: '0s',
      _metadata: metadata
    }
  };
}

// VOIR LE CODE COMPLET DANS LE README - Ce code est trop long pour tenir ici
// Copie le code du Node 11 depuis le README.md

const items = $input.all();

if (items.length === 1 && items[0].json.noRelevantDocs) {
  const metadata = items[0].json._metadata;
  const endTime = Date.now();
  const processingTime = ((endTime - metadata.startTime) / 1000).toFixed(1);

  return { json: { html: '<!DOCTYPE html><html><body><h1>Aucun document pertinent trouvé</h1></body></html>' } };
}

const metadata = items[0]?.json._metadata || {};
const endTime = Date.now();
const processingTime = ((endTime - metadata.startTime) / 1000).toFixed(1);

let documentCards = items.map(item => {
  const doc = item.json;
  return `<div class="document"><h3>${doc.fileName}</h3><p>${doc.analysis}</p></div>`;
}).join('');

const html = `<!DOCTYPE html>
<html lang="fr">
<head>
    <meta charset="UTF-8">
    <title>Analyse DCE</title>
</head>
<body>
    <h1>Analyse DCE</h1>
    <p>Temps: ${processingTime}s</p>
    ${documentCards}
</body>
</html>`;

return { json: { html } };
